type ServerEvent =
  | { type: 'message.created'; inboxCursor: number; conversationId: string; message: Message }
  | { type: 'read.updated'; inboxCursor: number; conversationId: string; userId: string; lastReadSequence: number }
  | { type: 'conversation.updated'; inboxCursor: number; summary: ConversationSummary };

type CatchUpResult =
  | { kind: 'events'; events: ServerEvent[]; inboxCursor: number }
  | { kind: 'resync-required' };

interface MessagingGateway {
  listConversations(input: { cursor: string | null; signal: AbortSignal }): Promise<{ items: ConversationSummary[]; nextCursor: string | null }>;
  loadOlder(input: { conversationId: string; beforeSequence: number; limit: number; signal: AbortSignal }): Promise<{ messages: Message[]; hasOlder: boolean }>;
  sendMessage(input: { conversationId: string; clientMessageId: string; body: string; signal: AbortSignal }): Promise<Message>;
  markRead(input: { conversationId: string; lastReadSequence: number }): Promise<void>;
  eventsAfter(input: { inboxCursor: number; signal: AbortSignal }): Promise<CatchUpResult>;
}

interface RealtimeChannel {
  connect(handlers: { onEvent(event: ServerEvent): void; onState(state: ConnectionState): void }): void;
  sendTyping(conversationId: string): void;
  close(): void;
}
